-- Read-only validation of the complete six-spell batch, dependencies, identities and references.
with settings as materialized(select $tech_core_spells${"schema":"wg-tech-core-introductory-spells-v1","source":{"id":900,"name":"Tech Core","url":"https://store.paizo.com/starfinder-tech-core/","group":"starfinder-core","required_content_sources":null},"sources":[{"id":900,"name":"Tech Core","user_id":null,"is_published":true,"deprecated":null},{"id":579,"name":"Starfinder Player Core","user_id":null,"is_published":true,"deprecated":null},{"id":3,"name":"Common Core","user_id":null,"is_published":true,"deprecated":false}],"references":[{"table":"ability_block","row":{"id":19611,"cost":null,"name":"Cast a Spell","type":"action","uuid":3222895456836016,"level":1,"access":null,"rarity":"COMMON","traits":[],"actions":null,"special":null,"trigger":null,"version":"1.0","frequency":null,"meta_data":{"foundry":{"rules":[]}},"created_at":"2023-12-13T20:30:43.277321+00:00","operations":[],"description":"Spells can vary in how many actions they take, as shown in the spell’s stat block. You cast cantrips, spells from spell slots, and focus spells using the same process, but must expend the spell when casting a spell from a spell slot and must spend 1 Focus Point to cast a focus spell. Some rules will refer to the Cast a Spell activity, such as “if the next action you use is to Cast a Spell.” Any spell qualifies as a Cast a Spell activity, and any characteristics of the spell use those of the specific spell you’re casting.\n\n### **Costs and Loci**\n\nSome spells require you to pay a cost or provide a locus. If the spell lists a cost, you must have the listed money, valuable materials, or other resources to cast the spell (such as gems or magical reagents), and they're expended during the casting.\n\nA locus is an object that funnels or directs the magical energy of the spell but is not consumed in its casting. As part of Casting the Spell, you retrieve the locus (if necessary, and if you have a free hand), and you can put it away again if you so choose. Loci tend to be expensive, and you need to acquire them in advance to cast the spell, but they aren't expended like costs are. Unless noted otherwise, a locus has negligible Bulk.\n\n### **Long Casting Times**\n\nSome spells take minutes or hours to cast. You can’t use other actions or reactions while casting such a spell, though at the GM’s discretion, you might be able to speak a few sentences. As with other activities that take a long time, these spells have the exploration trait, and you can’t cast them in an encounter. If combat breaks out while you’re casting one, your spell is disrupted.\n\n### **Disrupted and Lost Spells**\n\nSome abilities and spells can disrupt a spell, causing it to have no effect and be lost. When you lose a spell, you’ve already expended the spell slot and spent the spell’s costs and actions. If a spell is disrupted during a [Sustain](link_action_19858) action, the spell immediately ends.","availability":null,"requirements":null,"prerequisites":[],"content_source_id":3}},{"table":"ability_block","row":{"id":19632,"cost":null,"name":"Escape","type":"action","uuid":6836671321143633,"level":null,"access":null,"rarity":"COMMON","traits":[1520,1437],"actions":"ONE-ACTION","special":null,"trigger":null,"version":"1.0","frequency":null,"meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2296","book":"Player Core","page":"416"},"foundry":{"rules":[]}},"created_at":"2023-12-13T20:43:39.880464+00:00","operations":null,"description":"You attempt to escape from being Grabbed, Immobilized, or Restrained. Choose one creature, object, spell effect, hazard, or other impediment imposing any of those conditions on you. Attempt a check using your unarmed attack modifier against the DC of the effect. This is typically the Athletics DC of a creature grabbing you, the Thievery DC of a creature who tied you up, the spell DC for a spell effect, or the listed Escape DC of an object, hazard, or other impediment. You can attempt an Acrobatics or Athletics check instead of using your attack modifier if you choose (but this action still has the attack trait).\n\n**Critical Success** You get free and remove the grabbed, immobilized, and restrained conditions imposed by your chosen target. You can then Stride up to 5 feet.\n\n**Success** You get free and remove the grabbed, immobilized, and restrained conditions imposed by your chosen target.\n\n**Critical Failure** You don't get free, and you can't attempt to Escape again until your next turn.","availability":null,"requirements":null,"prerequisites":null,"content_source_id":3}},{"table":"ability_block","row":{"id":19722,"cost":null,"name":"Force Open","type":"action","uuid":6604590639704314,"level":null,"access":null,"rarity":"COMMON","traits":[1520,1438],"actions":"ONE-ACTION","special":null,"trigger":null,"version":"1.0","frequency":null,"meta_data":{"skill":"ATHLETICS","source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2375","book":"Player Core","page":"234"},"foundry":{"rules":[]}},"created_at":"2023-12-13T22:25:08.795626+00:00","operations":null,"description":"Using your body, a lever, or some other tool, you attempt to forcefully open a door, window, container or heavy gate. With a high enough result, you can even smash through walls. Without a crowbar, prying something open takes a –2 item penalty to the Athletics check to Force Open.\n\n**Critical Success** You open the door, window, container, or gate and can avoid damaging it in the process.\n\n**Success** You break the door, window, container, or gate open, and it gains the broken condition. If it's especially sturdy, the GM might have it take damage but not be broken.\n\n**Critical Failure** Your attempt jams the door, window, container, or gate shut, imposing a –2 circumstance penalty on future attempts to Force it Open.\n\nSample Force Open Tasks\n-----------------------\n\n*   **Untrained** fabric, flimsy glass\n*   **Trained** ice, sturdy glass\n*   **Expert** flimsy wooden door, wooden portcullis\n*   **Master** sturdy wooden door, iron portcullis, metal bar\n*   **Legendary** stone or iron door","availability":null,"requirements":null,"prerequisites":null,"content_source_id":3}},{"table":"ability_block","row":{"id":19858,"cost":null,"name":"Sustain","type":"action","uuid":7845751305633010,"level":null,"access":null,"rarity":"COMMON","traits":[1432],"actions":"ONE-ACTION","special":null,"trigger":null,"version":"1.0","frequency":null,"meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2317","book":"Player Core","page":"419"},"foundry":{"rules":[]}},"created_at":"2023-12-14T00:27:10.903097+00:00","operations":null,"description":"Choose one of your effects that has a sustained duration or lists a special benefit when you Sustain it. Most such effects come from spells or magic item activations. If the effect has a sustained duration, its duration extends until the end of your next turn. (Sustaining more than once in the same turn doesn't extend the duration to subsequent turns.) If an ability can be sustained but doesn't list how long, it can be sustained up to 10 minutes.\n\nAn effect might list an additional benefit that occurs if you Sustain it, and this can even appear on effects that don't have a sustained duration. If the effect has both a special benefit and a sustained duration, your Sustain action extends the duration as well as having the special benefit.\n\nIf your Sustain action is disrupted, the ability ends.","availability":null,"requirements":null,"prerequisites":null,"content_source_id":3}},{"table":"ability_block","row":{"id":27519,"cost":"","name":"Counteract","type":"action","uuid":5801842492515756,"level":1,"access":"","rarity":"COMMON","traits":[],"actions":null,"special":"","trigger":"","version":null,"frequency":"","meta_data":{},"created_at":"2024-05-21T17:05:26.731011+00:00","operations":[],"description":"Some effects try to counteract spells, afflictions, conditions, or other effects. Counteract checks compare the power of two forces and determine which defeats the other. Successfully counteracting an effect disrupts it, preventing it from having any effect, unless noted otherwise.\n\nWhen attempting a counteract check, add the relevant skill modifier or other appropriate modifier to your check against the target's DC. If you're counteracting an affliction, the DC is in the affliction's stat block. If it's a spell, use the caster's DC. The GM can also calculate a DC based on the target effect's level. For spells, the counteract check modifier is your spellcasting attribute modifier plus your spellcasting proficiency bonus, plus any bonuses and penalties that specifically apply to counteract checks.\n\nWhat you can counteract depends on the check result and the target's counteract rank. If an effect is a spell, its rank is the counteract rank. Otherwise, halve its level and round up to determine its counteract rank (minimum counteract rank 0). If an effect's level is unclear and it came from a creature, halve and round up the creature's level.\n\n**Critical Success** Counteract the target if its counteract rank is no more than 3 higher than your effect's counteract rank.\n\n**Success** Counteract the target if its counteract rank is no more than 1 higher than your effect's counteract rank.\n\n**Failure** Counteract the target if its counteract rank is lower than your effect's counteract rank.\n\n**Critical Failure** You fail to counteract the target.\n\n**Counteract Table**\n\nThis table provides a reference for what an effect can counteract based on its rank and the check result. The first number in each column is the counteract rank at which you can counteract an effect based on your degree of success. The numbers in parentheses are the typical level range corresponding to that rank.\n\n**Counteract**\n\n| Counteract Rank | Failure | Success | Critical Success |\n\n|:--:|:--:|:--:|:--:|\n\n| 0 | - | 1 ( 1 to 2) | 3 (5 to 6)|\n\n| 1 | 0 (-1 to 0) | 2 (3 to 4) | 4 (7 to 8)|\n\n| 2 | 1 (1 to 2) | 3 (5 to 6) | 5 (9 to 10)|\n\n| 3 | 2 (2 to 4) | 4 (7 to 8) | 6 (11 to 12)|\n\n| 4 | 3 (3 to 6) | 5 (9 to 10) | 7 (13 to 14)|\n\n| 5 | 4 (4 to 8) | 6 (11 to 12) | 8 (15 to 16)|\n\n| 6 | 5 (5 to 10) | 7 (13 to 14) | 9 (17 to 18)|\n\n| 7 | 6 (6 to 12) | 8 (15 to 16) | 10 (19 to 20)|\n\n| 8 | 7 (7 to 14) | 9 (17 to 18) | 11 (21 to 22)|\n\n| 9 | 8 (8 to 16) | 10 (19 to 20) | 12 (23 to 24)|\n\n| 10 | 9 (9 to 18) | 11 (21 to 22) | 13 (25 to 26)|","availability":null,"requirements":"","prerequisites":[],"content_source_id":3}},{"table":"ability_block","row":{"id":46744,"cost":"","name":"Install Upgrade","type":"action","uuid":1616544465714318,"level":1,"access":"","rarity":"COMMON","traits":[1457,1433],"actions":null,"special":"","trigger":"","version":null,"frequency":"","meta_data":{"source":{"url":"https://2e.aonsrd.com/actions/38-install-upgrade","book":"Starfinder Player Core","page":"431"}},"created_at":"2025-08-25T19:47:50.885625+00:00","operations":[],"description":"You spend 10 minutes installing an upgrade into a suit of armor or weapon, placing it into an empty upgrade slot. You can also use this activity to uninstall an upgrade. You can’t install more upgrades than there are upgrade slots. Installing or uninstalling an upgrade requires using a repair toolkit with two hands.","availability":null,"requirements":"You must use a repair toolkit.","prerequisites":[],"content_source_id":579}},{"table":"trait","row":{"id":1432,"name":"Concentrate","uuid":3011511166869167,"meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=561","book":"Player Core","page":"454"}},"created_at":"2023-12-02T22:32:54.192399+00:00","description":"An action with this trait requires a degree of mental concentration and discipline to perform.","content_source_id":3}},{"table":"trait","row":{"id":1433,"name":"Manipulate","uuid":2971108648217689,"meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=645","book":"Player Core","page":"458"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false},"created_at":"2023-12-02T22:32:55.850689+00:00","description":"You must physically manipulate an item or make gestures to use an action with this trait. Creatures without a suitable appendage can’t perform actions with this trait. Manipulate actions often trigger reactions.","content_source_id":3}},{"table":"trait","row":{"id":1508,"name":"Detection","uuid":3905705105933428,"meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=574","book":"Player Core","page":"455"}},"created_at":"2023-12-02T23:20:34.864578+00:00","description":"Effects with this trait attempt to determine the presence or location of a person, object, or aura.","content_source_id":3}},{"table":"trait","row":{"id":1520,"name":"Attack","uuid":1285342290589006,"meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=540","book":"Player Core","page":"452"},"important":true},"created_at":"2023-12-02T23:28:07.861361+00:00","description":"An ability with this trait involves an attack. For each attack you make beyond the first on your turn, you take a multiple attack penalty.","content_source_id":3}},{"table":"trait","row":{"id":1560,"name":"Force","uuid":1798173688310192,"meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=610","book":"Player Core","page":"456"}},"created_at":"2023-12-03T18:51:58.121654+00:00","description":"Effects with this trait deal force damage or create objects made of pure magical force.","content_source_id":3}},{"table":"trait","row":{"id":1582,"name":"Noisy","uuid":4266038592624261,"meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=660","book":"Player Core","page":"272"},"important":true},"created_at":"2023-12-03T18:54:25.518822+00:00","description":"This armor is loud and likely to alert others to your presence. The armor’s check penalty applies to Stealth checks even if you meet the required Strength score.","content_source_id":3}},{"table":"trait","row":{"id":1590,"name":"Scrying","uuid":570162919720558,"meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=689","book":"Player Core","page":"460"}},"created_at":"2023-12-03T18:56:32.850765+00:00","description":"A scrying effect lets you see, hear, or otherwise get sensory information from a distance using a sensor or apparatus, rather than your own eyes and ears.","content_source_id":3}},{"table":"trait","row":{"id":1858,"name":"Cantrip","uuid":7837841754363754,"meta_data":null,"created_at":"2023-12-13T08:04:05.408784+00:00","description":"A spell you can cast at will that is automatically heightened to half your level rounded up.","content_source_id":3}},{"table":"trait","row":{"id":4506,"name":"Tech","uuid":8353387345040544,"meta_data":{"source":{"url":"https://2e.aonsrd.com/traits/179-tech","book":"Starfinder Player Core","page":"455"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"created_at":"2025-06-27T23:38:56.418203+00:00","description":"Equipment with the tech trait rely on electricity and may gain the glitching condition. Some creatures and hazards also have the tech trait, such as artificial intelligence, robots, and turrets.\n\nArmor with the tech trait incorporate electronics, computer systems, integrated power sources, and a [comm unit](link_item_16072).\n\nShields with the tech trait incorporate electronics, computer systems, and integrated power sources.\n\nWeapons with the tech trait incorporate electronics, computer systems, and power sources. Usually the weapons rely on integrated power sources (such as melee weapons that don't have the [powered](link_trait_4670) trait), while others drain batteries with each attack.\n\nCybernetic augmentations are technological, not magical, though they aren't subject to any effect or attack that targets technology unless it specifies that it affects cybernetics.","content_source_id":579}},{"table":"trait","row":{"id":5225,"name":"Junk","uuid":8693519255012780,"meta_data":{"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"created_at":"2026-10-08T04:30:41.323377+00:00","description":"Spells with the junk trait use scrap, trash, and other debris found in any environment. While casting a junk spell requires no locus, it assumes the spellcaster always has access to discarded scraps or naturally occurring detritus. If the caster has absolutely nothing on their person or in their environment, they might be unable to cast a junk spell.","content_source_id":900}}],"rows":[{"name":"Bugfix","rank":0,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1858,1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 creature or object with the glitching condition","duration":"","description":"You release a magically self-editing line of code into the target, tackling the root cause of any technical failings afflicting it. You attempt to [counteract](link_action_27519) the glitching condition affecting the target. Regardless of the result, the target becomes immune to *[bugfix](link_spell_900000507)* for 1 minute.","heightened":{"text":[],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"149","url":"https://2e.aonsrd.com/spells/507-bugfix"}},"content_source_id":900,"version":"1.0","uuid":299866193306417},{"name":"Detect Technology","rank":0,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1858,1432,1508,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":"30-foot emanation","targets":"","duration":"","description":"You send out a pulse of magic that detects the presence of technology, including creatures, hazards, and objects with the [tech](link_trait_4506) trait. You receive no information beyond the presence or absence of technology. You can choose to ignore technology you're fully aware of, such as the technology of you and your allies and the ship you're traveling in.","heightened":{"text":[{"amount":"(3rd)","text":"You learn the level or rank of the most powerful technology, as determined by the GM."},{"amount":"(4th)","text":"As 3rd rank, but you also pinpoint the source of the highest-level or highest-ranked technology. Like for an imprecise sense, you don't learn the exact location but can narrow down the source to within a 5-foot cube (or the nearest if larger than that)."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"152","url":"https://2e.aonsrd.com/spells/508-detect-technology"}},"content_source_id":900,"version":"1.0","uuid":6023438549940619},{"name":"Emoticon","rank":0,"traditions":["arcane","divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1520,1858,1432,1560,1433],"defense":"AC","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"1 creature","duration":"","description":"You unleash a string of emoticons that bash against a creature. Make a spell attack roll against the target's AC, dealing 2d4 bludgeoning or [force](link_trait_1560) damage (chosen when you [Cast the Spell](link_action_19611)).","heightened":{"text":[{"amount":"(+1)","text":"The damage increases by 1d4."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"153","url":"https://2e.aonsrd.com/spells/437-emoticon"}},"content_source_id":900,"version":"1.0","uuid":1011056868991540},{"name":"Linked Sight","rank":0,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"ONE-ACTION","traits":[1858,1432,1433,1590],"defense":null,"cost":"","trigger":null,"requirements":"You have a scope, goggles, or some other optical tool, used as a locus.","range":"30 feet","area":null,"targets":"","duration":"5 minutes","description":"You toss the required locus to a point in range, imbuing the optic tool with a connection to your own vision. For the duration, the locus can see in all directions with your normal visual senses, though it treats sight as an imprecise sense past 15 feet. You can [Sustain](link_action_19858) the spell to switch between seeing through the locus or through your standard vision.","heightened":{"text":[{"amount":"(+1)","text":"The duration of the spell is increased by 5 minutes, and the range past which the locus's sight becomes imprecise is increased by 5 feet."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"157","url":"https://2e.aonsrd.com/spells/457-linked-sight"}},"content_source_id":900,"version":"1.0","uuid":2805567295624203},{"name":"Junk Armor","rank":1,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,5225,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"10 minutes","description":"You create light, medium, or heavy armor out of junk that you immediately don. You lose the benefits of any armor you were already wearing when you [Cast this Spell](link_action_19611), including any upgrades in that armor. You can create any common commercial grade armor, and it gains the [noisy](link_trait_1582) and [tech](link_trait_4506) traits if it doesn't have them already. It can't be made of any special materials.\n\nThe armor has one fewer upgrade slot than usual. When you [Cast this Spell](link_action_19611), you can automatically [Install](link_action_46744) any upgrades you're holding in your hands as a locus into any upgrade slots the armor has.","heightened":{"text":[{"amount":"(2nd)","text":"You can create tactical armor."},{"amount":"(5th)","text":"You can create advanced armor."},{"amount":"(6th)","text":"You can create superior armor."},{"amount":"(8th)","text":"You can create elite armor."},{"amount":"(9th)","text":"You can create ultimate armor."},{"amount":"(10th)","text":"You can create paragon armor."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"155","url":"https://2e.aonsrd.com/spells/448-junk-armor"}},"content_source_id":900,"version":"1.0","uuid":5420111739556292},{"name":"Junk Restraints","rank":1,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,5225,1433],"defense":"Reflex","cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 creature","duration":"","description":"Pieces of junk clamp around the target's limbs, locking them in place like a series of makeshift manacles. The target must attempt a Reflex saving throw.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature is suppressed for 1 round.\n\n**Failure** The creature is clumsy 1 and suppressed for 1 hour.\n\n**Critical Failure** As failure, but the creature is also restrained and drops all items it's holding in its space. The restraints' [Force Open](link_action_19722) and [Escape](link_action_19632) DCs are equal to your spell DC. A creature can attack the restraints in an attempt to break its grip. The restraints have AC equal to your spell DC, Hardness 5, and 20 Hit Points. Destroying, [Forcing Open](link_action_19722), or [Escaping](link_action_19632) from the restraints ends the spell.","heightened":{"text":[{"amount":"(3rd)","text":"The junk has Hardness 8 and 66 Hit Points."},{"amount":"(5th)","text":"The junk has Hardness 8 and 88 Hit Points."},{"amount":"(8th)","text":"The junk has Hardness 10 and 100 Hit Points."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"156","url":"https://2e.aonsrd.com/spells/451-junk-restraints"}},"content_source_id":900,"version":"1.0","uuid":5366499937587165}],"bindings":[{"uuid":299866193306417,"field":"description","href":"link_spell_900000507","template":"link_spell_{{allocated_id}}","occurrences":1}]}$tech_core_spells$::jsonb as spec),
expected as materialized(select p as row from settings cross join lateral jsonb_array_elements(spec->'rows') p),
bindings as materialized(select p from settings cross join lateral jsonb_array_elements(spec->'bindings') p),
actual as materialized(select e.row,r.id,case when b.p is null then e.row else jsonb_set(e.row,'{description}',to_jsonb(replace(e.row->>'description','('||(b.p->>'href')||')','('||replace(b.p->>'template','{{allocated_id}}',r.id::text)||')')),false) end as expected_row,
  to_jsonb(r)-'id'-'created_at'-'updated_at'-'search_tsv' as actual_row
  from expected e left join public.spell r on r.uuid=(e.row->>'uuid')::bigint
  left join bindings b on b.p->>'uuid'=e.row->>'uuid'),
aliases as materialized(select r.id from expected e join public.spell r on r.uuid=(e.row->>'uuid')::bigint
  or (r.content_source_id=900 and lower(btrim(r.name))=lower(btrim(e.row->>'name')))
  or lower(btrim(r.meta_data#>>'{source,url}'))=lower(btrim(e.row#>>'{meta_data,source,url}'))),
reference_rows as materialized(select 'trait'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.trait r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='trait')
  union all select 'ability_block',to_jsonb(r)-'updated_at'-'search_tsv' from public.ability_block r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='ability_block')),
dependencies as materialized(select coalesce(count(*)=16 and bool_and(r.row is not null and r.row=p->'row'),false) as passed
  from settings cross join lateral jsonb_array_elements(spec->'references') p
  left join reference_rows r on r.table_name=p->>'table' and r.row->>'id'=p#>>'{row,id}'),
sources as materialized(select coalesce(count(*)=3 and bool_and(s.id is not null and jsonb_build_object('id',s.id,'name',s.name,'user_id',s.user_id,'is_published',s.is_published,'deprecated',s.deprecated)=p),false)
  and exists(select 1 from public.content_source s where s.id=900 and s.name='Tech Core' and s.url='https://store.paizo.com/starfinder-tech-core/' and s."group"='starfinder-core' and s.required_content_sources is null) as passed
  from settings cross join lateral jsonb_array_elements(spec->'sources') p left join public.content_source s on s.id=(p->>'id')::bigint),
pending as materialized(select exists(select 1 from public.content_update u cross join settings where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in('APPROVED','REJECTED') and (
  (u.type='spell' and exists(select 1 from expected e where u.data->>'uuid'=e.row->>'uuid'
    or u.ref_id in(select id from actual where row->>'uuid'=e.row->>'uuid')
    or u.data->>'id' in(select id::text from actual where row->>'uuid'=e.row->>'uuid')
    or ((u.content_source_id=900 or u.data->>'content_source_id'='900') and lower(btrim(u.data->>'name'))=lower(btrim(e.row->>'name')))
    or lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(e.row#>>'{meta_data,source,url}'))))
  or exists(select 1 from jsonb_array_elements(spec->'references') p where u.type in(p->>'table',replace(p->>'table','_','-'),p#>>'{row,type}') and (
    u.ref_id=(p#>>'{row,id}')::bigint or u.data->>'id'=p#>>'{row,id}' or u.data->>'uuid'=p#>>'{row,uuid}'
    or ((u.content_source_id=(p#>>'{row,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{row,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{row,name}')))
    or (coalesce(btrim(p#>>'{row,meta_data,source,url}'),'')<>'' and lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(p#>>'{row,meta_data,source,url}')))))
  or (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or lower(btrim(u.data->>'name'))=lower(btrim(p->>'name'))))
)) as present),
state as(select (select passed from dependencies) and (select passed from sources) and not(select present from pending) as prerequisites,
  (select count(*) from aliases) as aliases,
  (select count(*) from actual where id>0 and actual_row=expected_row and position('900000507' in actual_row::text)=0) as exact_rows)
select 'tech-core-introductory-spells' as id,prerequisites and aliases=6 and exact_rows=6 as passed from state;
